VIEWED={338,363,364,423,424,457,458,469,470,479,485,493,496,498,513,514,522,528,529,551,562,564,566,567,571,587,588,593,598,604,605,612,613,615}
def f(text,p,section,evidence):return {'text':text,'refs':[{'source':'O','section':section,'pages':p if isinstance(p,list) else [p]}],'evidence':evidence}
def form(label,expr,note,p,sec,ev):return {'label':label,'expression':expr,'note':note,'refs':[{'source':'O','section':sec,'pages':p if isinstance(p,list) else [p]}],'evidence':ev}
def term(t,definition):return {'term':t,'definition':definition}
def base(n):
 d=json.loads((OLD/f'chapters/{n:02}.json').read_text('utf-8-sig'))
 return {'chapter':n,'title':d['title'],'source_code':'O','learning':[],'terms':[],'summary_basis':'','summary':[],'review':[],'cheat':{},'checked_images':[],'editor_notes':[],'corrections':[]}
def finish(x,terms,learning,summary,basis,review,defs,rows,ctitle='원문 비교',forms=None):
 x.update(terms=[term(t,v) for t,v in terms],learning=learning,summary=summary,summary_basis=basis,review=[{'question':q,'answer':a} for q,a in review],cheat={'definitions':[term(t,v) for t,v in defs],'comparison_title':ctitle,'comparison_headers':['구분','책의 설명'],'comparison_rows':rows,'formulas':forms or []})
 def walk(z):
  if isinstance(z,dict):
   for r in z.get('refs',[]):yield from r['pages']
   for v in z.values():yield from walk(v)
  elif isinstance(z,list):
   for v in z:yield from walk(v)
 pages=set(walk(x));x['checked_images']=sorted(pages&VIEWED)
 (OUT/f'{x["chapter"]:02}.json').write_text(json.dumps(x,ensure_ascii=False,indent=2),'utf-8')
 print(x['chapter'],'cited',sorted(pages),'unchecked',sorted(pages-VIEWED))

